from pathlib import Path
import re
for p in sorted(Path('main').glob('*.c')):
    lines=p.read_text(errors='replace').splitlines()
    if len(lines)>=250:
        print(f'FILE {len(lines):4d} {p}')
    starts=[]
    pat=re.compile(r'^(?:static\s+)?(?:[A-Za-z_][\w\s\*]*?)\s+([A-Za-z_]\w*)\s*\(')
    for i,line in enumerate(lines,1):
        s=line.strip()
        if s.startswith(('if ','if(', 'for ','for(', 'while ','while(', 'switch ','return ')) or s.endswith(';'):
            continue
        m=pat.match(s)
        if m: starts.append((i,m.group(1)))
    for n,(start,name) in enumerate(starts):
        end=(starts[n+1][0]-1) if n+1<len(starts) else len(lines)
        if end-start+1>=80:
            print(f'FUNC {end-start+1:4d} {p}:{start} {name}')
